<?php/** * Transparency Center — Tab: Content Hub — V1.0.4 *  * @package MegaGovern * @since   1.0.4 * @var array $megagovern_args */if ( ! defined( 'ABSPATH' ) ) {    exit;}use MegaGovern\Helpers;// ─── VARIABLE DECLARATION WITH PROPER PREFIX ──────────────────────$megagovern_filter        = isset( $args['filter'] ) ? sanitize_text_field( wp_unslash( $args['filter'] ) ) : 'all';$megagovern_post_type     = isset( $args['post_type'] ) ? sanitize_text_field( wp_unslash( $args['post_type'] ) ) : 'all';$megagovern_search        = isset( $args['search'] ) ? sanitize_text_field( wp_unslash( $args['search'] ) ) : '';$megagovern_paged         = isset( $args['paged'] ) ? intval( wp_unslash( $args['paged'] ) ) : 1;$megagovern_stats         = isset( $args['stats'] ) ? (array) $args['stats'] : [];$megagovern_undeclared    = isset( $args['undeclared'] ) ? intval( wp_unslash( $args['undeclared'] ) ) : 0;$megagovern_has_pro       = isset( $args['has_pro'] ) ? (bool) $args['has_pro'] : false;$megagovern_is_agency     = isset( $args['is_agency'] ) ? (bool) $args['is_agency'] : false;$megagovern_nonce_bulk    = isset( $args['nonce_bulk'] ) ? sanitize_text_field( wp_unslash( $args['nonce_bulk'] ) ) : '';$megagovern_nonce_history = isset( $args['nonce_history'] ) ? sanitize_text_field( wp_unslash( $args['nonce_history'] ) ) : '';$megagovern_single_nonce  = wp_create_nonce( 'megagovern_single_declare' );$megagovern_scan_nonce    = wp_create_nonce( 'megagovern_scan' );$megagovern_query         = isset( $args['query'] ) ? $args['query'] : null;// Validate WP_Queryif ( null !== $megagovern_query && ! ( $megagovern_query instanceof WP_Query ) ) {    $megagovern_query = null;}$megagovern_total     = isset( $megagovern_stats['total'] ) ? intval( $megagovern_stats['total'] ) : 0;$megagovern_human     = isset( $megagovern_stats['human'] ) ? intval( $megagovern_stats['human'] ) : 0;$megagovern_assisted  = isset( $megagovern_stats['ai_assisted'] ) ? intval( $megagovern_stats['ai_assisted'] ) : 0;$megagovern_generated = isset( $megagovern_stats['ai_generated'] ) ? intval( $megagovern_stats['ai_generated'] ) : 0;$megagovern_all_count = $megagovern_total + $megagovern_undeclared;/** * Get registered public post types for filtering */$megagovern_registered_types = get_post_types( [ 'public' => true ], 'objects' );$megagovern_registered_types['attachment'] = get_post_type_object( 'attachment' );if ( ! function_exists( 'megagovern_content_icon' ) ) {    /**     * Render a Lucide inline SVG icon.     *     * @param string $name Icon identifier.     * @param string $size Width/height in pixels.     * @return string SVG markup.     */    function megagovern_content_icon( string $name, string $size = '16' ): string {        $icons = [            'file'        => '<svg xmlns="http://www.w3.org/2000/svg" width="' . esc_attr( $size ) . '" height="' . esc_attr( $size ) . '" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M14 2H6a2 2 0 0 0-2 2v16a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2V8z"/><polyline points="14 2 14 8 20 8"/></svg>',            'users'       => '<svg xmlns="http://www.w3.org/2000/svg" width="' . esc_attr( $size ) . '" height="' . esc_attr( $size ) . '" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M16 21v-2a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v2"/><circle cx="9" cy="7" r="4"/><path d="M22 21v-2a4 4 0 0 1 0 7.75"/><path d="M16 3.13a4 4 0 0 1 0 7.75"/></svg>',            'edit'        => '<svg xmlns="http://www.w3.org/2000/svg" width="' . esc_attr( $size ) . '" height="' . esc_attr( $size ) . '" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M17 3a2.85 2.85 0 1 1 4 4L7.5 20.5 2 22l1.5-5.5Z"/></svg>',            'cpu'         => '<svg xmlns="http://www.w3.org/2000/svg" width="' . esc_attr( $size ) . '" height="' . esc_attr( $size ) . '" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><rect x="4" y="4" width="16" height="16" rx="2"/><rect x="9" y="9" width="6" height="6"/></svg>',            'alert'       => '<svg xmlns="http://www.w3.org/2000/svg" width="' . esc_attr( $size ) . '" height="' . esc_attr( $size ) . '" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="m21.73 18-8-14a2 2 0 0 0-3.48 0l-8 14A2 2 0 0 0 4 21h16a2 2 0 0 0 1.73-3Z"/><line x1="12" y1="9" x2="12" y2="13"/><line x1="12" y1="17" x2="12.01" y2="17"/></svg>',            'search'      => '<svg xmlns="http://www.w3.org/2000/svg" width="' . esc_attr( $size ) . '" height="' . esc_attr( $size ) . '" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><circle cx="11" cy="11" r="8"/><line x1="21" y1="21" x2="16.65" y2="16.65"/></svg>',            'clock'       => '<svg xmlns="http://www.w3.org/2000/svg" width="' . esc_attr( $size ) . '" height="' . esc_attr( $size ) . '" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><circle cx="12" cy="12" r="10"/><polyline points="12 6 12 12 16 14"/></svg>',            'check'       => '<svg xmlns="http://www.w3.org/2000/svg" width="' . esc_attr( $size ) . '" height="' . esc_attr( $size ) . '" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><polyline points="20 6 9 17 4 12"/></svg>',            'refresh-cw'  => '<svg xmlns="http://www.w3.org/2000/svg" width="' . esc_attr( $size ) . '" height="' . esc_attr( $size ) . '" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><polyline points="23 4 23 10 17 10"/><polyline points="1 20 1 14 7 14"/><path d="M3.51 9a9 9 0 0 1 14.85-3.36L23 10M1 14l4.64 4.36A9 9 0 0 0 20.49 15"/></svg>',        ];        return isset( $icons[ $name ] ) ? $icons[ $name ] : '';    }}?><!-- Metrics Cards --><div class="mga-gov-metrics">    <div class="mga-gov-metric">        <div class="mga-gov-metric-icon" style="background: rgba(0,0,0,0.04);">            <?php echo wp_kses_post( megagovern_content_icon( 'file', '18' ) ); ?>        </div>        <div>            <div class="mga-gov-metric-val"><?php echo esc_html( (string) $megagovern_all_count ); ?></div>            <div class="mga-gov-metric-label"><?php esc_html_e( 'Total Indexed', 'megagovern' ); ?></div>        </div>    </div>    <div class="mga-gov-metric">        <div class="mga-gov-metric-icon" style="background: #eff6ff;">            <?php echo wp_kses_post( megagovern_content_icon( 'users', '18' ) ); ?>        </div>        <div>            <div class="mga-gov-metric-val"><?php echo esc_html( (string) $megagovern_human ); ?></div>            <div class="mga-gov-metric-label"><?php esc_html_e( 'Human Made', 'megagovern' ); ?></div>        </div>    </div>    <div class="mga-gov-metric">        <div class="mga-gov-metric-icon" style="background: #ecfdf5;">            <?php echo wp_kses_post( megagovern_content_icon( 'edit', '18' ) ); ?>        </div>        <div>            <div class="mga-gov-metric-val"><?php echo esc_html( (string) $megagovern_assisted ); ?></div>            <div class="mga-gov-metric-label"><?php esc_html_e( 'AI Modified', 'megagovern' ); ?></div>        </div>    </div>    <div class="mga-gov-metric">        <div class="mga-gov-metric-icon" style="background: #fef2f2;">            <?php echo wp_kses_post( megagovern_content_icon( 'cpu', '18' ) ); ?>        </div>        <div>            <div class="mga-gov-metric-val"><?php echo esc_html( (string) $megagovern_generated ); ?></div>            <div class="mga-gov-metric-label"><?php esc_html_e( 'Fully AI-Generated', 'megagovern' ); ?></div>        </div>    </div></div><!-- Undeclared Alert --><?php if ( $megagovern_undeclared > 0 ) : ?>    <div class="mga-gov-alert">        <div class="mga-gov-alert-content">            <?php echo wp_kses_post( megagovern_content_icon( 'alert', '16' ) ); ?>            <span>                <?php                /* translators: %d: number of unclassified items */                printf( esc_html__( '%d unclassified items detected.', 'megagovern' ), esc_html( $megagovern_undeclared ) );                ?>            </span>        </div>        <?php        $megagovern_review_url = add_query_arg(            array(                'page' => 'megagovern-transparency',                'gtab' => 'catalog',                'declaration_filter' => 'undeclared',                'post_type_filter' => 'all'            ),            admin_url( 'admin.php' )        );        ?>        <a href="<?php echo esc_url( $megagovern_review_url ); ?>"            class="button button-link" style="color: #991b1b; font-weight: 600;">            <?php esc_html_e( 'Review Undeclared', 'megagovern' ); ?> &rarr;        </a>    </div><?php endif; ?><!-- Content Review Queue --><div class="mga-card mga-card--review-queue" style="margin-bottom: 16px;">    <div class="mga-card-body" style="display: flex; align-items: center; justify-content: space-between; flex-wrap: wrap; gap: 12px; padding: 12px 16px;">        <div style="display: flex; align-items: center; gap: 10px;">            <span class="mga-review-queue-icon">                <?php echo wp_kses_post( megagovern_content_icon( 'search', '18' ) ); ?>            </span>            <div>                <strong style="font-size: 13px;">                    <?php esc_html_e( 'Content Review Queue', 'megagovern' ); ?>                </strong>                <?php if ( $megagovern_undeclared > 0 ) : ?>                    <span class="mga-badge mga-badge--warning" style="margin-left: 8px; font-size: 11px;">                        <?php echo esc_html( (string) $megagovern_undeclared ); ?>                    </span>                    <p style="font-size: 11px; color: #646970; margin: 2px 0 0;">                        <?php esc_html_e( 'Undeclared posts found. Run a review to classify them.', 'megagovern' ); ?>                    </p>                <?php else : ?>                    <span class="mga-badge mga-badge--success" style="margin-left: 8px; font-size: 11px;">                        <?php esc_html_e( 'Clear', 'megagovern' ); ?>                    </span>                    <p style="font-size: 11px; color: #1e7a34; margin: 2px 0 0;">                        <?php esc_html_e( 'All content has been declared.', 'megagovern' ); ?>                    </p>                <?php endif; ?>            </div>        </div>        <button type="button" class="button" id="mga_scan_btn" data-nonce="<?php echo esc_attr( $megagovern_scan_nonce ); ?>">            <?php echo wp_kses_post( megagovern_content_icon( 'refresh-cw', '14' ) ); ?>            <?php echo $megagovern_undeclared > 0 ? esc_html__( 'Review Now', 'megagovern' ) : esc_html__( 'Re-scan', 'megagovern' ); ?>        </button>    </div>    <div id="mga_scan_status" style="display: none; padding: 8px 16px; font-size: 12px; color: #646970; border-top: 1px solid #e5e7eb;"></div></div><!-- Bulk Declaration + Filter Controls --><div class="mga-gov-controls">    <div class="mga-card" style="margin-bottom: 0;">        <h3 class="mga-card-title" style="font-size: 11px; text-transform: uppercase;">            <?php esc_html_e( 'Bulk Declaration', 'megagovern' ); ?>        </h3>        <p style="font-size: 10px; color: var(--mga-muted); margin: 0 0 8px;">            <?php esc_html_e( 'Select items and classify them all at once.', 'megagovern' ); ?>        </p>        <div class="mga-gov-bulk-row">            <select id="bulk_action" class="mga-gov-select" style="flex: 1;">                <option value=""><?php esc_html_e( 'Select classification...', 'megagovern' ); ?></option>                <option value="human"><?php esc_html_e( 'Human Made', 'megagovern' ); ?></option>                <option value="ai_assisted"><?php esc_html_e( 'AI Modified', 'megagovern' ); ?></option>                <option value="ai_generated"><?php esc_html_e( 'Fully AI-Generated', 'megagovern' ); ?></option>                <option value="deepfake"><?php esc_html_e( 'Synthetic Media', 'megagovern' ); ?></option>            </select>            <button type="button" class="button button-primary mga-gov-btn" id="bulk_execute_btn">                <?php esc_html_e( 'Classify Selected', 'megagovern' ); ?>            </button>        </div>        <div class="mga-gov-bulk-info">            <span><strong id="selected_count">0</strong> <?php esc_html_e( 'selected', 'megagovern' ); ?></span>            <span id="bulk_result" class="mga-gov-bulk-result"></span>        </div>    </div>    <div class="mga-card" style="margin-bottom: 0;">        <h3 class="mga-card-title" style="font-size: 11px; text-transform: uppercase;">            <?php esc_html_e( 'Filter & Search', 'megagovern' ); ?>        </h3>        <form method="get" action="<?php echo esc_url( admin_url( 'admin.php' ) ); ?>" class="mga-gov-filter-row">            <input type="hidden" name="page" value="megagovern-transparency">            <input type="hidden" name="gtab" value="catalog">                        <select name="declaration_filter" class="mga-gov-select">                <option value="all" <?php selected( $megagovern_filter, 'all' ); ?>><?php esc_html_e( 'All Statuses', 'megagovern' ); ?></option>                <option value="human" <?php selected( $megagovern_filter, 'human' ); ?>><?php esc_html_e( 'Human Made', 'megagovern' ); ?></option>                <option value="ai_assisted" <?php selected( $megagovern_filter, 'ai_assisted' ); ?>><?php esc_html_e( 'AI Modified', 'megagovern' ); ?></option>                <option value="ai_generated" <?php selected( $megagovern_filter, 'ai_generated' ); ?>><?php esc_html_e( 'Fully AI-Generated', 'megagovern' ); ?></option>                <option value="deepfake" <?php selected( $megagovern_filter, 'deepfake' ); ?>><?php esc_html_e( 'Synthetic Media', 'megagovern' ); ?></option>                <option value="undeclared" <?php selected( $megagovern_filter, 'undeclared' ); ?>><?php esc_html_e( 'Undeclared', 'megagovern' ); ?></option>            </select>                        <select name="post_type_filter" class="mga-gov-select">                <option value="all" <?php selected( $megagovern_post_type, 'all' ); ?>><?php esc_html_e( 'All Types', 'megagovern' ); ?></option>                <?php foreach ( $megagovern_registered_types as $megagovern_pt_key => $megagovern_pto ) :                     if ( ! $megagovern_pto ) continue;                    $megagovern_label = ( $megagovern_pt_key === 'attachment' ) ? __( 'Media Library', 'megagovern' ) : $megagovern_pto->labels->singular_name;                ?>                    <option value="<?php echo esc_attr( $megagovern_pt_key ); ?>" <?php selected( $megagovern_post_type, $megagovern_pt_key ); ?>>                        <?php echo esc_html( $megagovern_label ); ?>                    </option>                <?php endforeach; ?>            </select>                        <input type="text" name="s" class="mga-gov-input"                    placeholder="<?php esc_attr_e( 'Search...', 'megagovern' ); ?>"                    value="<?php echo esc_attr( $megagovern_search ); ?>">                        <button type="submit" class="button button-secondary mga-gov-btn">                <?php esc_html_e( 'Apply', 'megagovern' ); ?>            </button>                        <?php            $megagovern_reset_url = add_query_arg(                array(                    'page' => 'megagovern-transparency',                    'gtab' => 'catalog'                ),                admin_url( 'admin.php' )            );            ?>            <a href="<?php echo esc_url( $megagovern_reset_url ); ?>" class="button button-link">                <?php esc_html_e( 'Reset', 'megagovern' ); ?>            </a>                        <span class="mga-gov-result-count">                <?php                 if ( $megagovern_query && method_exists( $megagovern_query, 'found_posts' ) ) {                    echo esc_html( (string) $megagovern_query->found_posts );                } else {                    echo '0';                }                ?>                 <?php esc_html_e( 'results', 'megagovern' ); ?>            </span>        </form>    </div></div><!-- Content Table --><div class="mga-gov-table-wrap">    <?php if ( $megagovern_query && $megagovern_query->have_posts() ) : ?>        <table class="mga-gov-table">            <thead>                <tr>                    <th style="width: 40px;"><input type="checkbox" id="select_all"></th>                    <th style="width: 65px;"><?php esc_html_e( 'ID', 'megagovern' ); ?></th>                    <th><?php esc_html_e( 'Content', 'megagovern' ); ?></th>                    <th style="width: 170px;"><?php esc_html_e( 'Declaration', 'megagovern' ); ?></th>                    <th style="width: 130px;"><?php esc_html_e( 'Authorized By', 'megagovern' ); ?></th>                    <th style="width: 110px;"><?php esc_html_e( 'Declared', 'megagovern' ); ?></th>                    <th style="width: 110px; text-align: right;"><?php esc_html_e( 'Actions', 'megagovern' ); ?></th>                </tr>            </thead>            <tbody>                <?php while ( $megagovern_query->have_posts() ) : $megagovern_query->the_post();                     $megagovern_pid       = get_the_ID();                    $megagovern_ptype     = get_post_type();                    $megagovern_dec       = get_post_meta( $megagovern_pid, '_megagovern_declaration', true );                    $megagovern_dec_by    = get_post_meta( $megagovern_pid, '_megagovern_declared_by', true );                    $megagovern_dec_at    = get_post_meta( $megagovern_pid, '_megagovern_declared_at', true );                    $megagovern_pto       = get_post_type_object( $megagovern_ptype );                    $megagovern_has       = ! empty( $megagovern_dec );                    $megagovern_row_class = $megagovern_has ? '' : 'row-undeclared';                                        // Safe declaration info retrieval                    $megagovern_dec_info = null;                    if ( $megagovern_has && class_exists( 'MegaGovern\Helpers' ) && method_exists( 'MegaGovern\Helpers', 'declaration_type' ) ) {                        $megagovern_dec_info = Helpers::declaration_type( $megagovern_dec );                    }                                        $megagovern_edit_link = ( $megagovern_ptype === 'attachment' ) ? admin_url( 'post.php?post=' . $megagovern_pid . '&action=edit' ) : get_edit_post_link( $megagovern_pid );                    $megagovern_title     = ( $megagovern_ptype === 'attachment' ) ? get_the_title( $megagovern_pid ) : get_the_title();                ?>                    <tr class="<?php echo esc_attr( $megagovern_row_class ); ?>" id="post-row-<?php echo esc_attr( (string) $megagovern_pid ); ?>">                        <td><input type="checkbox" class="dec_checkbox" value="<?php echo esc_attr( (string) $megagovern_pid ); ?>"></td>                        <td class="mga-gov-table-id">#<?php echo esc_html( (string) $megagovern_pid ); ?></td>                        <td>                            <strong>                                <a href="<?php echo esc_url( $megagovern_edit_link ); ?>" class="mga-gov-post-link">                                    <?php echo esc_html( $megagovern_title ?: __( '(No Title)', 'megagovern' ) ); ?>                                </a>                            </strong>                            <div class="mga-gov-post-meta">                                <?php echo esc_html( $megagovern_pto ? $megagovern_pto->labels->singular_name : $megagovern_ptype ); ?>                                &middot;                                <?php echo esc_html( get_the_author() ); ?>                            </div>                        </td>                        <td>                            <div class="mga-quick-declaration-wrapper" data-post-id="<?php echo esc_attr( (string) $megagovern_pid ); ?>">                                <?php if ( $megagovern_has && is_array( $megagovern_dec_info ) ) : ?>                                    <span class="mga-status <?php echo esc_attr( isset( $megagovern_dec_info['css'] ) ? $megagovern_dec_info['css'] : 'mga-status-undeclared' ); ?>" style="display: inline-flex; align-items: center; gap: 4px;">                                        <?php echo wp_kses_post( megagovern_content_icon( isset( $megagovern_dec_info['icon'] ) ? $megagovern_dec_info['icon'] : 'file' ) ); ?>                                        <?php echo esc_html( isset( $megagovern_dec_info['label'] ) ? $megagovern_dec_info['label'] : __( 'Unknown', 'megagovern' ) ); ?>                                    </span>                                <?php else : ?>                                    <span class="mga-status mga-status-undeclared"><?php esc_html_e( 'Unassigned', 'megagovern' ); ?></span>                                <?php endif; ?>                            </div>                        </td>                        <td class="mga-gov-table-meta">                            <?php                             if ( ! empty( $megagovern_dec_by ) ) {                                $megagovern_user = get_userdata( (int) $megagovern_dec_by );                                echo esc_html( $megagovern_user ? $megagovern_user->display_name : 'User #' . $megagovern_dec_by );                            } else {                                 echo '&mdash;';                             }                            ?>                        </td>                        <td class="mga-gov-table-time">                            <?php                             if ( ! empty( $megagovern_dec_at ) ) {                                /* translators: %s: human readable time difference */                                echo esc_html( sprintf( __( '%s ago', 'megagovern' ), human_time_diff( strtotime( $megagovern_dec_at ) ) ) );                            } else {                                echo '&mdash;';                            }                            ?>                        </td>                        <td style="text-align: right;">                            <div style="display: inline-flex; gap: 4px; align-items: center;">                                <select class="mga-quick-declare-select" data-post-id="<?php echo esc_attr( (string) $megagovern_pid ); ?>" style="font-size: 11px; padding: 2px 4px; height: 26px;">                                    <option value=""><?php esc_html_e( 'Review...', 'megagovern' ); ?></option>                                    <option value="human" <?php selected( $megagovern_dec, 'human' ); ?>><?php esc_html_e( 'Human', 'megagovern' ); ?></option>                                    <option value="ai_assisted" <?php selected( $megagovern_dec, 'ai_assisted' ); ?>><?php esc_html_e( 'Modified', 'megagovern' ); ?></option>                                    <option value="ai_generated" <?php selected( $megagovern_dec, 'ai_generated' ); ?>><?php esc_html_e( 'Generated', 'megagovern' ); ?></option>                                    <option value="deepfake" <?php selected( $megagovern_dec, 'deepfake' ); ?>><?php esc_html_e( 'Synthetic', 'megagovern' ); ?></option>                                </select>                                <button type="button" class="button button-small mga-history-btn"                                         data-post-id="<?php echo esc_attr( (string) $megagovern_pid ); ?>"                                        data-nonce="<?php echo esc_attr( $megagovern_nonce_history ); ?>"                                        title="<?php esc_attr_e( 'View History', 'megagovern' ); ?>">                                    <?php echo wp_kses_post( megagovern_content_icon( 'clock', '14' ) ); ?>                                </button>                            </div>                        </td>                    </tr>                <?php endwhile; wp_reset_postdata(); ?>            </tbody>        </table>        <script>        jQuery(document).ready(function($) {            // ─── Quick Review ──────────────────────────────────────────            $('.mga-quick-declare-select').on('change', function() {                var $select = $(this);                var postId = $select.data('post-id');                var newType = $select.val();                                if (!newType) {                    return;                }                $select.prop('disabled', true);                $.ajax({                    url: ajaxurl,                    type: 'POST',                    data: {                        action: 'megagovern_single_declare',                        nonce: <?php echo wp_json_encode( $megagovern_single_nonce ); ?>,                        post_id: postId,                        type: newType                    },                    success: function(response) {                        if (response.success) {                            location.reload();                        } else {                            alert(response.data && response.data.message ? response.data.message : '<?php echo esc_js( __( 'Error updating declaration.', 'megagovern' ) ); ?>');                            $select.prop('disabled', false);                        }                    },                    error: function() {                        alert('<?php echo esc_js( __( 'Server error occurred.', 'megagovern' ) ); ?>');                        $select.prop('disabled', false);                    }                });            });            // ─── Select All ────────────────────────────────────────────            $('#select_all').on('change', function() {                $('.dec_checkbox').prop('checked', $(this).prop('checked'));                updateSelectedCount();            });            $('.dec_checkbox').on('change', function() {                updateSelectedCount();            });            function updateSelectedCount() {                var count = $('.dec_checkbox:checked').length;                $('#selected_count').text(count);            }            // ─── Bulk Declaration ──────────────────────────────────────            $('#bulk_execute_btn').on('click', function() {                var selected = [];                $('.dec_checkbox:checked').each(function() {                    selected.push($(this).val());                });                                if (selected.length === 0) {                    alert('<?php echo esc_js( __( 'Please select at least one item.', 'megagovern' ) ); ?>');                    return;                }                                var bulkAction = $('#bulk_action').val();                if (!bulkAction) {                    alert('<?php echo esc_js( __( 'Please select a classification.', 'megagovern' ) ); ?>');                    return;                }                                if (!confirm('<?php echo esc_js( __( 'Apply this classification to all selected items?', 'megagovern' ) ); ?>')) {                    return;                }                                var $btn = $(this);                $btn.prop('disabled', true).text('<?php echo esc_js( __( 'Processing...', 'megagovern' ) ); ?>');                                $.ajax({                    url: ajaxurl,                    type: 'POST',                    data: {                        action: 'megagovern_bulk_declare',                        nonce: <?php echo wp_json_encode( $megagovern_nonce_bulk ); ?>,                        post_ids: JSON.stringify(selected),                        declaration_type: bulkAction                    },                    success: function(response) {                        if (response.success) {                            location.reload();                        } else {                            alert(response.data && response.data.message ? response.data.message : '<?php echo esc_js( __( 'Failed to apply declarations.', 'megagovern' ) ); ?>');                            $btn.prop('disabled', false).text('<?php echo esc_js( __( 'Classify Selected', 'megagovern' ) ); ?>');                        }                    },                    error: function() {                        alert('<?php echo esc_js( __( 'Server error occurred.', 'megagovern' ) ); ?>');                        $btn.prop('disabled', false).text('<?php echo esc_js( __( 'Classify Selected', 'megagovern' ) ); ?>');                    }                });            });            // ─── Content Review Queue ──────────────────────────────────            $('#mga_scan_btn').on('click', function() {                var $btn    = $(this);                var $status = $('#mga_scan_status');                                $btn.prop('disabled', true).text('<?php echo esc_js( __( 'Scanning...', 'megagovern' ) ); ?>');                $status.hide().text('');                                $.ajax({                    url: ajaxurl,                    type: 'POST',                    data: {                        action: 'megagovern_scan_start',                        nonce: $btn.data('nonce')                    },                    success: function(response) {                        if (response.success) {                            var url = new URL(window.location.href);                            url.searchParams.set('declaration_filter', 'undeclared');                            url.searchParams.set('post_type_filter', 'all');                            url.searchParams.delete('paged');                            window.location.href = url.toString();                        } else {                            $status.text(response.data && response.data.message ? response.data.message : '<?php echo esc_js( __( 'Scan failed.', 'megagovern' ) ); ?>').show();                            $btn.prop('disabled', false).html('<?php echo wp_kses_post( megagovern_content_icon( 'refresh-cw', '14' ) ); ?> <?php echo esc_js( __( 'Review Now', 'megagovern' ) ); ?>');                        }                    },                    error: function() {                        $status.text('<?php echo esc_js( __( 'Server error. Please try again.', 'megagovern' ) ); ?>').show();                        $btn.prop('disabled', false).html('<?php echo wp_kses_post( megagovern_content_icon( 'refresh-cw', '14' ) ); ?> <?php echo esc_js( __( 'Review Now', 'megagovern' ) ); ?>');                    }                });            });            // ─── History Modal ─────────────────────────────────────────            $(document).on('click', '.mga-history-btn', function() {                var $btn   = $(this);                var postId = $btn.data('post-id');                var nonce  = $btn.data('nonce');                if (!nonce) {                    alert('<?php echo esc_js( __( 'Security token missing. Please refresh the page.', 'megagovern' ) ); ?>');                    return;                }                // Remove any existing modal                $('#mga-history-modal').remove();                $.ajax({                    url: ajaxurl,                    type: 'GET',                    data: {                        action: 'megagovern_get_history',                        post_id: postId,                        ajax_nonce: nonce                    },                    success: function(response) {                        if (response.success && response.data && response.data.html) {                            var modal =                                 '<div class="mga-modal" id="mga-history-modal" style="display:block;position:fixed;top:0;left:0;width:100%;height:100%;z-index:99999;">' +                                '<div class="mga-modal-overlay" style="position:absolute;top:0;left:0;width:100%;height:100%;background:rgba(0,0,0,0.4);"></div>' +                                '<div class="mga-modal-content" style="position:absolute;top:50%;left:50%;transform:translate(-50%,-50%);background:#fff;max-width:480px;max-height:400px;overflow-y:auto;border-radius:8px;box-shadow:0 20px 60px rgba(0,0,0,0.3);padding:20px;">' +                                '<button type="button" class="mga-modal-close" style="float:right;background:none;border:none;font-size:24px;cursor:pointer;color:#666;line-height:1;" aria-label="<?php esc_attr_e( 'Close', 'megagovern' ); ?>">&times;</button>' +                                '<div style="padding:8px 0;">' + response.data.html + '</div>' +                                '</div></div>';                            $('body').append(modal);                        } else {                            alert('<?php echo esc_js( __( 'Could not load history.', 'megagovern' ) ); ?>');                        }                    },                    error: function() {                        alert('<?php echo esc_js( __( 'Server error occurred.', 'megagovern' ) ); ?>');                    }                });            });            // ─── Close Modal ──────────────────────────────────────────            $(document).on('click', '.mga-modal-overlay, .mga-modal-close', function() {                $('#mga-history-modal').fadeOut(150, function() {                    $(this).remove();                });            });        });        </script>        <?php if ( $megagovern_query->max_num_pages > 1 ) : ?>            <div class="mga-gov-pagination">                <?php                echo wp_kses_post( paginate_links( array(                    'base'      => add_query_arg( 'paged', '%#%' ),                    'format'    => '',                    'current'   => $megagovern_paged,                    'total'     => $megagovern_query->max_num_pages,                    'prev_text' => '&larr;',                    'next_text' => '&rarr;',                ) ) );                ?>            </div>        <?php endif; ?>    <?php else : ?>        <div class="mga-empty" style="text-align: center; padding: 40px;">            <?php echo wp_kses_post( megagovern_content_icon( 'search', '32' ) ); ?>            <h3><?php esc_html_e( 'No Content Found', 'megagovern' ); ?></h3>            <p><?php esc_html_e( 'Adjust filters or run a new Review to find undeclared content.', 'megagovern' ); ?></p>        </div>    <?php endif; ?></div>